    team_id bigint,big_chances integer,big_chances_missed integer,
    shots_on_target_per_match numeric,set_piece_goals integer,set_piece_xg numeric,
    set_piece_goals_conceded integer,set_piece_xga numeric,
    touches_in_opposition_box integer,possession_percentage numeric,
    shot_conversion_rate numeric,aggregate_source text
  )
)
update public.scout_team_tactical_profiles p
set big_chances=src.big_chances,
    big_chances_missed=src.big_chances_missed,
    shots_on_target_per_match=src.shots_on_target_per_match,
    set_piece_goals=src.set_piece_goals,
    set_piece_xg=src.set_piece_xg,
    set_piece_goals_conceded=src.set_piece_goals_conceded,
    set_piece_xga=src.set_piece_xga,
    touches_in_opposition_box=src.touches_in_opposition_box,
    possession_percentage=src.possession_percentage,
    shot_conversion_rate=src.shot_conversion_rate,
    aggregate_source=src.aggregate_source,
    aggregate_updated_at=now(),
    updated_at=now()
from src
where p.season='2026-27' and p.team_id=src.team_id;

grant select(
  big_chances,big_chances_missed,shots_on_target_per_match,
  set_piece_goals,set_piece_xg,set_piece_goals_conceded,set_piece_xga,
  aggregate_source,aggregate_updated_at,touches_in_opposition_box,
  possession_percentage,shot_conversion_rate
) on public.scout_team_tactical_profiles to anon,authenticated;

with totals as (
  select p.team_id,sum(coalesce(s.xg_total,0)+coalesce(s.xa_total,0)) denom
  from public.scout_player_season_stats s
  join public.scout_players p on p.id=s.player_id
  where s.season='2026-27' and p.active=true
  group by p.team_id
)
update public.scout_player_season_stats s
set attack_contribution_share=
      case when totals.denom>0
           then (coalesce(s.xg_total,0)+coalesce(s.xa_total,0))/totals.denom
           else 0 end,
    advanced_updated_at=coalesce(s.advanced_updated_at,now())
from public.scout_players p
join totals on totals.team_id=p.team_id
where s.season='2026-27' and s.player_id=p.id and p.active=true;

create or replace function public.scout_enrichment_qa()
returns jsonb
language sql
stable
security invoker
set search_path='public'
as $qa$
with active as (
  select p.id,p.primary_role,s.xa_model_per90,s.xa_per90,s.attack_contribution_share
  from scout_players p
  left join scout_player_season_stats s
    on s.player_id=p.id and s.season='2026-27'
  where p.active=true
), teams as (
  select t.id,tp.coverage,tp.big_chances,tp.shots_on_target_per_match,
         tp.touches_in_opposition_box,tp.possession_percentage,tp.shot_conversion_rate
  from scout_teams t
  left join scout_team_tactical_profiles tp
    on tp.team_id=t.id and tp.season='2026-27'
  where t.active=true
)
select jsonb_build_object(
  'active_players',(select count(*) from active),
  'xa_model_covered',(select count(*) from active where xa_model_per90 is not null),
  'xa_observed_covered',(select count(*) from active where xa_per90 is not null),
  'xa_fallback_only',(select count(*) from active where xa_per90 is null and xa_model_per90 is not null),
  'attack_share_covered',(select count(*) from active where attack_contribution_share is not null),
  'detailed_role_covered',(select count(*) from active where primary_role not in ('DEF_UNKNOWN','MID_UNKNOWN','FWD_UNKNOWN')),
  'unknown_role',(select count(*) from active where primary_role in ('DEF_UNKNOWN','MID_UNKNOWN','FWD_UNKNOWN') or primary_role is null),
  'active_teams',(select count(*) from teams),
  'team_profile_covered',(select count(*) from teams where coverage is not null),
  'team_aggregate_profile_covered',(select count(*) from teams
    where big_chances is not null
      and shots_on_target_per_match is not null
      and touches_in_opposition_box is not null
      and possession_percentage is not null
      and shot_conversion_rate is not null),
  'team_event_profile_covered',(select count(*) from teams where coverage in ('partial_events','event_complete'))
);
$qa$;

grant execute on function public.scout_enrichment_qa() to anon,authenticated,service_role;

commit;
